"""Generate the standalone Go launcher's version from Python project metadata."""

from __future__ import annotations

import argparse
import json
import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if generation is needed")
    args = parser.parse_args()
    version = tomllib.loads((ROOT / "pyproject.toml").read_text())["project"]["version"]
    content = (
        "// Code generated by scripts/sync_version.py; DO NOT EDIT.\n"
        "package cli\n\n"
        f"const version = {json.dumps(version)}\n"
    )
    target = ROOT / "internal/cli/version_generated.go"
    if not target.exists() or target.read_text() != content:
        if args.check:
            print(
                "ERROR: run python3 scripts/sync_version.py to update the Go version",
                file=sys.stderr,
            )
            return 1
        target.write_text(content)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
